module logic;
use model {Summary};
use util {reverse};
record Cursor {pos:I64,frames:List<Bytes>,consumed:I64,error:I64,done:Bool}
fn run(data:Bytes,limit:I64)->Summary {
  let initial = Cursor {pos:0,frames:List::empty<Bytes>(),consumed:0,error:0,done:false};
  let final = while(state:Cursor=initial;state.pos < Bytes::length(data) && !state.done) {
    let start = state.pos;
    let n = Bytes::at(data,start);
    if n > limit {
      Cursor {...state,consumed:start,error:3,done:true}
    } else {
      if start + n + 2 > Bytes::length(data) {
        Cursor {...state,consumed:start,error:1,done:true}
      } else {
        let payload = Bytes::slice(data,start + 1,n);
        let checksum = Bytes::at(data,start + n + 1);
        let total = fold(i in n,total:I64=0) {total + Bytes::at(payload,i)};
        if total % 256 != checksum {
          Cursor {...state,consumed:start,error:2,done:true}
        } else {
          Cursor {...state,pos:start + n + 2,frames:List::prepend(payload,state.frames),consumed:start + n + 2}
        }
      }
    }
  };
  Summary {frames:reverse(final.frames),consumed:final.consumed,error:final.error}
}
